// 버전4(실험) 나무 데이터 — 마인크래프트/복셀 스타일 2차 시도. 첫 시도는 가지가
// 실사처럼 유기적으로 구부러져 있어서 마인크래프트 느낌이 안 난다는 피드백을 받아,
// 각진 그리드 블록으로 된 가지 사진 + 잎도 개별 낱장이 아니라 덩어리째 자라는 큐빅
// 블록 클러스터로 전부 교체함. 버전3과 같은 방식(가지만 있는 나무 사진을 격자로
// 스캔해 실제 가지 픽셀만 앵커로 씀, 몸통·뿌리 제외, 두께에 따라 앞/뒤 두 그룹)을 그대로
// 따름. v2, v3와 완전히 분리된 파일이라 이 파일을 고쳐도 실제 서비스나 다른 버전에는
// 영향 없음.

function seededRandom(seed) {
  let s = seed | 0;
  return function () {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffledAnchors(list) {
  const arr = [...list];
  const rand = seededRandom(20260921);
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

// tree-bare-voxel2.png 원본 픽셀 크기와, 그 사진을 SVG 로컬 좌표(GROUND_ANCHOR=(120,232)
// 기준)에 배치하는 스케일/오프셋. 트렁크 밑동 픽셀(638,1289)을 GROUND_ANCHOR에 맞춤.
const TREE_PHOTO_W = 1217;
const TREE_PHOTO_H = 1293;
const TREE_PHOTO_SCALE = 0.1841;
const TREE_PHOTO_OFFSET_X = 120 - 638 * TREE_PHOTO_SCALE;
const TREE_PHOTO_OFFSET_Y = 232 - 1289 * TREE_PHOTO_SCALE;

export const TREE_V4_IMAGE = {
  src: '/images/v4-minecraft/tree-bare-voxel2.png',
  x: TREE_PHOTO_OFFSET_X,
  y: TREE_PHOTO_OFFSET_Y,
  width: TREE_PHOTO_W * TREE_PHOTO_SCALE,
  height: TREE_PHOTO_H * TREE_PHOTO_SCALE,
};

function photoToSvg(px, py) {
  return { x: TREE_PHOTO_OFFSET_X + px * TREE_PHOTO_SCALE, y: TREE_PHOTO_OFFSET_Y + py * TREE_PHOTO_SCALE };
}

