export function getLeafV4(index) {
  const anchor = LEAF_ANCHORS_V4[index % LEAF_ANCHORS_V4.length];
  const ring = Math.floor(index / LEAF_ANCHORS_V4.length);
  const rand = seededRandom(index * 2654435761 + 7);
  const anchorAngleRad = (anchor.angle * Math.PI) / 180;
  let jitterAngle;
  let radius;
  if (ring === 0) {
    jitterAngle = rand() * Math.PI * 2;
    radius = 0.4 + rand() * 0.5;
  } else {
    jitterAngle = anchorAngleRad + (rand() - 0.5) * Math.PI * 0.9;
    radius = 0.6 + Math.min(ring * 0.18, 2.4) + rand() * 0.5;
  }
  const variant = LEAF_IMAGES_V4[index % LEAF_IMAGES_V4.length];
  // 복셀 그림은 고정된 카메라 각도로 빛/그림자가 이미 그려져 있어서 회전을 주지 않음
  const rot = 0;
  return {
    x: anchor.x + Math.cos(jitterAngle) * radius,
    y: anchor.y + Math.sin(jitterAngle) * radius * 0.85,
    rot,
    scale: 0.55 + rand() * 0.3,
    variant,
    behind: anchor.behind,
  };
}

// 그냥 5개마다 하나씩 뽑으면(셔플된 순서라도) 앵커가 가까이 몰려있는 자리끼리 뽑힐 수 있어서,
// 포도송이 이미지가 넓다 보니 여러 개가 겹쳐 뭉친 덩어리처럼 보였음 — 이미 고른 자리들과
// 일정 거리 이상 떨어진 자리만 순서대로 골라서 포도송이끼리 서로 안 겹치게 함
function minDistanceFilter(anchors, minDist, maxCount) {
  const picked = [];
  for (const a of anchors) {
    if (picked.every((p) => Math.hypot(p.x - a.x, p.y - a.y) >= minDist)) {
      picked.push(a);
      if (picked.length >= maxCount) break;
    }
  }
  return picked;
}
export const FRUIT_SPOTS_V4 = minDistanceFilter(LEAF_ANCHORS_V4, 14, Math.floor(LEAF_ANCHORS_V4.length / 5)).map((a) => ({
  x: a.x, y: a.y, behind: a.behind,
}));
